type Lang = 'bn' | 'en';
type Bi = { bn: string; en: string };
const copy = (lang: Lang, bn: string, en: string) => lang === 'bn' ? bn : en;
const normalizeText = (text: string) => text.replaceAll('\\n', '\n');
const val = (data: any, key: string, lang: Lang, fallback = ''): string => {
  const raw = data?.[key];
  if (typeof raw === 'string') return normalizeText(raw);
  if (raw && typeof raw === 'object') {
    const value = raw[lang] || raw.en || raw.bn || fallback;
    return typeof value === 'string' ? normalizeText(value) : fallback;
  }
  return fallback;
};
const optionalAgeLimit = (value: unknown): number | null =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0 && value <= 120
