     <div className="mt-14 flex items-center justify-between gap-6 sm:mt-20"><div className="flex items-center gap-3"><span className="home-mark text-[9px] text-[#edc7b3]">{String(Math.min(slide+1,Math.max(heroSources.length,1))).padStart(2,'0')} / {String(Math.max(heroSources.length,1)).padStart(2,'0')}</span><span className="h-px w-10 bg-[#f3e3d5]/35 sm:w-16"/><span className="text-[11px] tracking-wide text-[#f3e3d5]/65">{copy(lang,'চাটখিল পাঁচগাঁও মাহবুব সরকারি কলেজ ইউনিট','CHATKHIL PANCHGAON MAHBUB GOVERNMENT COLLEGE UNIT')}</span></div>
      {heroSources.length>1&&<span className="hidden shrink-0 items-center gap-1.5 text-[10px] tracking-wide text-[#f3e3d5]/50 sm:flex"><ArrowLeft size={12}/>{copy(lang,'সোয়াইপ করুন','Swipe')}<ArrowRight size={12}/></span>}</div>
