 useEffect(()=>{if(data&&!ready){const s:any=data.settings||{};const h:any=data.home||{};setFields({nameBn:val(s,'unitName','bn'),nameEn:val(s,'unitName','en'),missionBn:val(h,'mission','bn'),missionEn:val(h,'mission','en'),taglineBn:val(s,'tagline','bn'),taglineEn:val(s,'tagline','en'),email:val(s,'email','en','Chatkhilcollege2023@gmail.com'),phone:val(s,'phone','en','032275002'),website:val(s,'website','en','cmpe.edu.bd'),minAge:optionalAgeLimit(s.minAge)===null?'':String(s.minAge),maxAge:optionalAgeLimit(s.maxAge)===null?'':String(s.maxAge)});setReady(true)}},[data,ready]);
 const save=(e:any)=>{e.preventDefault();setMessage('');const minAge=fields.minAge===''?null:Number(fields.minAge);const maxAge=fields.maxAge===''?null:Number(fields.maxAge);if((minAge!==null&&(!Number.isInteger(minAge)||minAge<0||minAge>120))||(maxAge!==null&&(!Number.isInteger(maxAge)||maxAge<0||maxAge>120))||(minAge!==null&&maxAge!==null&&minAge>maxAge)){setMessage(copy(lang,'বয়সের সীমা ০–১২০ পূর্ণসংখ্যা হতে হবে এবং সর্বনিম্ন বয়স সর্বোচ্চ বয়সের চেয়ে বেশি হতে পারবে না।','Age limits must be whole numbers from 0 to 120, and the minimum cannot exceed the maximum.'));return}const payload={settings:{unitName:{bn:fields.nameBn,en:fields.nameEn},tagline:{bn:fields.taglineBn,en:fields.taglineEn},email:fields.email.trim(),phone:fields.phone.trim(),website:fields.website.trim(),minAge,maxAge},home:{mission:{bn:fields.missionBn,en:fields.missionEn}}};update.mutate({data:payload},{onSuccess:()=>{setMessage(copy(lang,'সাইট সেটিংস সংরক্ষিত হয়েছে।','Site settings saved.'));client.invalidateQueries({queryKey:getGetSiteQueryKey()});client.invalidateQueries({queryKey:getGetAdminOverviewQueryKey()})},onError:()=>setMessage(copy(lang,'সংরক্ষণ করা যায়নি। আবার চেষ্টা করুন।','Could not save. Please try again.'))})};
