 return <><div className="eyebrow">{copy(lang,'সাইট পরিচালনা','SITE SETTINGS')}</div><h1 className="display mt-2 text-3xl font-extrabold">{copy(lang,'সাইট পরিচিতি ও হোমপেজ','Site identity & homepage')}</h1><p className="mt-2 text-sm text-stone-500">{copy(lang,'প্রকাশিত সাইটে দেখা যাবে এমন দ্বিভাষিক পরিচিতি সম্পাদনা করুন।','Edit bilingual identity and homepage copy shown on the public site.')}</p><form onSubmit={save} className="mt-7 max-w-3xl rounded-2xl border border-rose-100 bg-white p-6 sm:p-8"><h2 className="font-extrabold">{copy(lang,'ইউনিটের পরিচিতি','Unit identity')}</h2><div className="mt-5 grid gap-4 sm:grid-cols-2">{field('nameBn',bilingual('ইউনিটের নাম · বাংলা','Unit name · Bangla'))}{field('nameEn',bilingual('ইউনিটের নাম · English','Unit name · English'))}{field('taglineBn',bilingual('ট্যাগলাইন · বাংলা','Tagline · Bangla'))}{field('taglineEn',bilingual('ট্যাগলাইন · English','Tagline · English'))}</div><h2 className="mt-8 font-extrabold">{copy(lang,'যোগাযোগের তথ্য','Contact information')}</h2><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">{copy(lang,'ইমেইল','Email')}<input type="email" required value={fields.email} onChange={e=>setFields({...fields,email:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 px-3 py-3" data-testid="input-setting-email"/></label><label className="text-sm font-semibold">{copy(lang,'ফোন','Phone')}<input required value={fields.phone} onChange={e=>setFields({...fields,phone:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 px-3 py-3" data-testid="input-setting-phone"/></label><label className="text-sm font-semibold">{copy(lang,'ওয়েবসাইট','Website')}<input required value={fields.website} onChange={e=>setFields({...fields,website:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 px-3 py-3" data-testid="input-setting-website"/></label></div><h2 className="mt-8 font-extrabold">{copy(lang,'ঐচ্ছিক বয়সসীমা','Optional age limits')}</h2><p className="mt-1 text-sm text-stone-500">{copy(lang,'ফাঁকা রাখলে কোনো বয়সসীমা থাকবে না।','Leave both fields blank to allow applicants of any age.')}</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">{copy(lang,'সর্বনিম্ন বয়স','Minimum age')}<input type="number" min="0" max="120" step="1" value={fields.minAge} onChange={e=>setFields({...fields,minAge:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 px-3 py-3" data-testid="input-setting-min-age"/></label><label className="text-sm font-semibold">{copy(lang,'সর্বোচ্চ বয়স','Maximum age')}<input type="number" min="0" max="120" step="1" value={fields.maxAge} onChange={e=>setFields({...fields,maxAge:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 px-3 py-3" data-testid="input-setting-max-age"/></label></div><h2 className="mt-8 font-extrabold">{copy(lang,'হোমপেজের অঙ্গীকার','Homepage mission')}</h2><div className="mt-4 grid gap-4 sm:grid-cols-2">{(['missionBn','missionEn'] as const).map((k,i)=><label key={k} className="text-sm font-semibold">{i===0?copy(lang,'অঙ্গীকার · বাংলা','Mission · Bangla'):copy(lang,'অঙ্গীকার · English','Mission · English')}<textarea rows={4} value={fields[k]} onChange={e=>setFields({...fields,[k]:e.target.value})} className="mt-2 w-full rounded-xl border border-rose-200 p-3" data-testid={`input-setting-${k}`}/></label>)}</div>{message&&<p className="mt-4 text-sm text-[#8F0A1F]" role="status" data-testid="settings-message">{message}</p>}<button disabled={update.isPending} className="mt-6 inline-flex items-center gap-2 rounded-full bg-[#C8102E] px-5 py-3 text-sm font-bold text-white disabled:opacity-60" data-testid="button-save-settings"><Save size={15}/>{update.isPending?copy(lang,'সংরক্ষণ হচ্ছে…','Saving…'):copy(lang,'পরিবর্তন সংরক্ষণ','Save changes')}</button></form></>;
