   <div className="mt-6 grid gap-3 rounded-2xl bg-[#fff7f7] p-4 text-sm sm:grid-cols-2"><div><span className="text-stone-500">{copy(lang,'শিক্ষাবর্ষ','Academic year')}</span><div className="mt-1 font-bold">{record.academicYear||'—'}</div></div><div><span className="text-stone-500">{copy(lang,'জমার সময়','Submitted')}</span><div className="mt-1 font-bold">{record.submittedAt?new Date(record.submittedAt).toLocaleString(lang==='bn'?'bn-BD':'en-BD'):'—'}</div></div><div><span className="text-stone-500">{copy(lang,'রোল নম্বর','Roll number')}</span><div className="mt-1 font-bold">{record.rollNo||'—'}</div></div><div><span className="text-stone-500">{copy(lang,'অভিভাবকের মোবাইল','Guardian mobile')}</span><div className="mt-1 font-mono font-bold">{record.guardianMobile||'—'}</div></div></div>
