 const mark=(m:any)=>{setActive(m);if(!m.read)read.mutate({id:m.id},{onSuccess:()=>client.invalidateQueries({queryKey:getGetAdminMessagesQueryKey()})})};
 return <><div className="flex items-end justify-between gap-4"><div><div className="eyebrow">{copy(lang,'যোগাযোগ','CONTACT')}</div><h1 className="display mt-2 text-3xl font-extrabold">{copy(lang,'বার্তা ইনবক্স','Contact inbox')}</h1><p className="mt-2 text-sm text-stone-500">{copy(lang,'সাইটের যোগাযোগ ফর্ম থেকে পাঠানো বার্তা।','Messages sent through the public contact form.')}</p></div><span className="rounded-full bg-white px-3 py-2 text-xs font-bold">{messages.filter(m=>!m.read).length} {copy(lang,'অপঠিত','unread')}</span></div>
 {query.isLoading?<div className="mt-6"><Skeletons/></div>:query.isError?<div className="mt-6"><ErrorState lang={lang} onRetry={()=>query.refetch()}/></div>:messages.length?<div className="mt-6 grid gap-3">{messages.map((m:any)=><button key={m.id} onClick={()=>mark(m)} className={`flex items-start gap-4 rounded-2xl border p-5 text-left transition hover:border-rose-300 ${m.read?'border-rose-100 bg-white':'border-rose-200 bg-[#fff7f7]'}`} data-testid={`message-${m.id}`}><span className={`mt-1 h-2.5 w-2.5 shrink-0 rounded-full ${m.read?'bg-stone-300':'bg-[#C8102E]'}`}/><span className="min-w-0 flex-1"><span className="flex flex-wrap justify-between gap-2"><b>{m.name} <span className="font-normal text-stone-500">· {m.subject}</span></b><span className="text-[10px] text-stone-400">{new Date(m.createdAt).toLocaleDateString(lang==='bn'?'bn-BD':'en-BD')}</span></span><span className="mt-1 block truncate text-sm text-stone-600">{m.message}</span><span className="mt-2 block text-xs text-[#8F0A1F]">{m.email}{m.phone&&` · ${m.phone}`}</span></span></button>)}</div>:<div className="mt-6"><EmptyState lang={lang}/></div>}
 {active&&<div className="fixed inset-0 z-50 grid place-items-center bg-[#18080d]/55 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-xl rounded-2xl bg-white p-6"><div className="flex justify-between"><div><div className="eyebrow">{active.email}</div><h2 className="mt-2 text-2xl font-extrabold">{active.subject}</h2></div><button onClick={()=>setActive(null)} className="grid h-9 w-9 place-items-center rounded-full bg-rose-50" aria-label="Close" data-testid="button-close-message"><X/></button></div><p className="mt-5 text-sm leading-7 text-stone-700">{active.message}</p><div className="mt-5 border-t border-rose-100 pt-4 text-sm">{active.name}{active.phone&&` · ${active.phone}`}</div><div className="mt-5 flex justify-end"><a href={`mailto:${active.email}?subject=${encodeURIComponent(active.subject)}`} className="rounded-full bg-[#C8102E] px-4 py-2.5 text-sm font-bold text-white no-underline" data-testid="link-reply-message">{copy(lang,'ইমেইলে উত্তর দিন','Reply by email')}</a></div></div></div>}
 </>;
